import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DqVSm8kp.js";const n="/llmxray/docs/educators/token-pipeline.svg",i="/llmxray/docs/educators/bpe-process.svg",s="/llmxray/docs/educators/strawberry-tokenization.svg",l="/llmxray/docs/educators/language-bias.svg",b=JSON.parse('{"title":"Module 1: What Is a Token?","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-1.md","filePath":"en/community/educators/module-1.md"}'),d={name:"en/community/educators/module-1.md"};function h(c,e,u,g,p,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="module-1-what-is-a-token" tabindex="-1">Module 1: What Is a Token? <a class="header-anchor" href="#module-1-what-is-a-token" aria-label="Permalink to &quot;Module 1: What Is a Token?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Observer</strong> — See the invisible</p><p><strong>Duration:</strong> 45 min | <strong>Difficulty:</strong> Beginner | <strong>Prerequisite:</strong> None</p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>AI doesn&#39;t think in words. It thinks in tokens. And tokens aren&#39;t what you expect.</p></blockquote><p>This is the foundational insight that changes everything about how students understand language models. Every concept that follows — temperature, context windows, embeddings, tool calling — depends on understanding what tokens really are.</p><p><img src="'+n+'" alt="From Text to Token to Prediction"></p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="what-is-a-token" tabindex="-1">What is a token? <a class="header-anchor" href="#what-is-a-token" aria-label="Permalink to &quot;What is a token?&quot;">​</a></h3><p>A <strong>token</strong> is the smallest unit of text that a language model processes. Tokens are not words, not characters, not syllables — they are <strong>subword units</strong> determined by a statistical algorithm trained on a large corpus.</p><p>The dominant algorithm is <strong>Byte-Pair Encoding (BPE)</strong>, introduced to NLP by Sennrich et al. (2016). BPE starts with individual characters and iteratively merges the most frequent adjacent pairs until reaching a target vocabulary size (typically 32,000-128,000 tokens).</p><p>For example, the word &quot;understanding&quot; might be tokenized as:</p><ul><li><code>[&quot;under&quot;, &quot;stand&quot;, &quot;ing&quot;]</code> (3 tokens)</li></ul><p>While &quot;AI&quot; might be:</p><ul><li><code>[&quot;AI&quot;]</code> (1 token — it&#39;s common enough to be a single entry)</li></ul><h3 id="why-does-tokenization-matter" tabindex="-1">Why does tokenization matter? <a class="header-anchor" href="#why-does-tokenization-matter" aria-label="Permalink to &quot;Why does tokenization matter?&quot;">​</a></h3><p>Every aspect of LLM behavior is measured in tokens:</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Token impact</th></tr></thead><tbody><tr><td><strong>Cost</strong></td><td>API pricing is per-token</td></tr><tr><td><strong>Speed</strong></td><td>Models generate one token per inference step</td></tr><tr><td><strong>Context window</strong></td><td>The maximum number of tokens the model can see at once</td></tr><tr><td><strong>Quality</strong></td><td>Token boundaries affect what the model can &quot;see&quot; within a word</td></tr><tr><td><strong>Fairness</strong></td><td>Languages with fewer tokens in the vocabulary require more tokens per sentence</td></tr></tbody></table><h3 id="how-bpe-works-simplified" tabindex="-1">How BPE works (simplified) <a class="header-anchor" href="#how-bpe-works-simplified" aria-label="Permalink to &quot;How BPE works (simplified)&quot;">​</a></h3><ol><li>Start with all individual bytes (256 base tokens)</li><li>Count all adjacent pairs in the training corpus</li><li>Merge the most frequent pair into a new token</li><li>Repeat until reaching the target vocabulary size</li></ol><p>This means:</p><ul><li>Common words become single tokens: <code>&quot;the&quot;</code>, <code>&quot;and&quot;</code>, <code>&quot;is&quot;</code></li><li>Rare words are split into pieces: <code>&quot;tokenization&quot;</code> → <code>[&quot;token&quot;, &quot;ization&quot;]</code></li><li>Very rare words go down to individual characters</li></ul><p>The LLaMA 3 family uses a BPE tokenizer with a 128,000-token vocabulary, trained primarily on English text (Grattafiori et al., 2024).</p><p><img src="'+i+'" alt="How BPE Tokenization Works"></p><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-see-tokens-arrive-in-real-time" tabindex="-1">Exercise 1: See tokens arrive in real-time <a class="header-anchor" href="#exercise-1-see-tokens-arrive-in-real-time" aria-label="Permalink to &quot;Exercise 1: See tokens arrive in real-time&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open <strong>Chat Diagnostics</strong> in LLMxRay and select a model (e.g., <code>llama3.2</code>)</li><li>Send: <em>&quot;Explain what gravity is in one sentence&quot;</em></li><li>Watch the tokens stream in one by one — each token appears as the model produces it</li><li>Open the <strong>Stream</strong> tab — see each token with its timestamp and inter-token latency</li><li>Notice the <strong>confidence coloring</strong>: green tokens arrived fast (high confidence), orange/red tokens arrived slowly (lower confidence)</li></ol><p><strong>What to observe:</strong></p><ul><li>Tokens are not always complete words. You&#39;ll see partial words, punctuation, and spaces as separate tokens.</li><li>Some tokens arrive almost instantly (the model was very certain). Others take longer (the model was &quot;choosing&quot; between options).</li><li>The first token takes the longest (Time to First Token / TTFT) — this is when the model processes your entire prompt.</li></ul><div class="info custom-block"><p class="custom-block-title">What is confidence coloring?</p><p>LLMxRay approximates token confidence from <strong>inter-token latency</strong>. Faster generation suggests the model had a dominant next-token prediction. This is a practical approximation — for mathematically precise confidence, the Benchmark feature uses real logprobs from the OpenAI-compatible endpoint. See Module 3 for the full story on confidence vs truth.</p></div><hr><h3 id="exercise-2-the-tokenizer-shock" tabindex="-1">Exercise 2: The tokenizer shock <a class="header-anchor" href="#exercise-2-the-tokenizer-shock" aria-label="Permalink to &quot;Exercise 2: The tokenizer shock&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>In chat, ask: <em>&quot;Count the letters in the word &#39;strawberry&#39;&quot;</em></li><li>The model will likely say 10 — but <code>strawberry</code> has 10 letters with 3 r&#39;s. Many models count 2 r&#39;s, not 3.</li><li>Now ask: <em>&quot;How many words are in this sentence: The quick brown fox jumps over the lazy dog&quot;</em></li><li>The model gets this right (9 words) — word counting is easier than letter counting</li></ol><p><strong>Why this happens:</strong></p><p>The word <code>strawberry</code> is tokenized as something like <code>[&quot;str&quot;, &quot;aw&quot;, &quot;berry&quot;]</code> — the model never sees the individual letters. It processes these chunks as atomic units. Counting letters requires character-level reasoning, but the model operates at the token level.</p><p>This is not a bug — it&#39;s a fundamental consequence of subword tokenization. The model literally cannot &quot;see&quot; individual letters within a token.</p><p><img src="'+s+'" alt="Why LLMs Can&#39;t Count Letters in Strawberry"></p><div class="tip custom-block"><p class="custom-block-title">Try it yourself</p><p>Visit the <a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">Tiktokenizer playground</a> or the <a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">HuggingFace Tokenizer Playground</a> to visualize how different models tokenize the same text. Compare how <code>llama</code> and <code>gpt-4</code> tokenize <code>&quot;strawberry&quot;</code> — they may split it differently.</p></div><p><strong>Research context:</strong> Fu et al. (2024) conducted a systematic study of this phenomenon in their paper <em>&quot;Why Do Large Language Models Struggle to Count Letters?&quot;</em> They found that errors correlate strongly with letter frequency and word length, not with how often the word appears in training data — confirming that the limitation is architectural (tokenization), not a knowledge gap.</p><hr><h3 id="exercise-3-language-bias-in-tokenization" tabindex="-1">Exercise 3: Language bias in tokenization <a class="header-anchor" href="#exercise-3-language-bias-in-tokenization" aria-label="Permalink to &quot;Exercise 3: Language bias in tokenization&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Send this prompt to the model: <em>&quot;Say hello in one sentence&quot;</em></li><li>Open the <strong>Stream</strong> tab and count the tokens in the response</li><li>Now send: <em>&quot;Dis bonjour en une phrase&quot;</em> (same request in French)</li><li>Count the tokens again — the French response will likely use more tokens</li><li>Try the same in German, Spanish, Chinese, Arabic, or any other language you know</li><li>Record the token counts for each language</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>The same semantic content requires <strong>significantly more tokens</strong> in non-English languages. This isn&#39;t because French is &quot;more complex&quot; — it&#39;s because the tokenizer&#39;s vocabulary was built primarily from English text.</p><table tabindex="0"><thead><tr><th>Language</th><th>Typical token ratio vs English</th></tr></thead><tbody><tr><td>English</td><td>1.0x (baseline)</td></tr><tr><td>French</td><td>1.3-1.5x</td></tr><tr><td>German</td><td>1.4-1.6x</td></tr><tr><td>Chinese</td><td>1.5-2.0x</td></tr><tr><td>Arabic</td><td>2.0-3.0x</td></tr><tr><td>Some African languages</td><td>Up to 5-15x</td></tr></tbody></table><p><img src="'+l+'" alt="Tokenizer Language Bias"></p><p><strong>Why this matters in practice:</strong></p><ul><li>A French user hits the context window limit <strong>30-50% sooner</strong> than an English user</li><li>API costs are <strong>proportionally higher</strong> for non-English languages</li><li>Generation is <strong>slower</strong> (more tokens to produce for the same content)</li><li>Quality may degrade because the model has fewer &quot;thinking tokens&quot; available</li></ul><div class="warning custom-block"><p class="custom-block-title">This is an active area of research</p><p>Petrov et al. (2023) showed in their NeurIPS paper <em>&quot;Language Model Tokenizers Introduce Unfairness Between Languages&quot;</em> that the same text can require up to <strong>15x more tokens</strong> in some languages compared to English, across 17 different tokenizers. This is not just a theoretical concern — it has real cost, latency, and quality implications.</p><p>Explore their <a href="https://aleksandarpetrov.github.io/tokenization-fairness/" target="_blank" rel="noreferrer">interactive demo</a> to see the disparity across languages.</p></div><hr><h3 id="exercise-4-speed-and-confidence" tabindex="-1">Exercise 4: Speed and confidence <a class="header-anchor" href="#exercise-4-speed-and-confidence" aria-label="Permalink to &quot;Exercise 4: Speed and confidence&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Have several conversations with the model on different topics</li><li>For each response, observe the confidence coloring in the token stream</li><li>Notice patterns: <ul><li>Common phrases (&quot;I think&quot;, &quot;The answer is&quot;) → green (fast, confident)</li><li>Technical terms, numbers, proper nouns → more orange (slower, less certain)</li><li>Creative or unusual phrasing → most orange/red (slowest, least certain)</li></ul></li><li>Open two Stream tabs side by side (from different sessions) and compare latency distributions</li></ol><p><strong>What to reflect on:</strong></p><ul><li>Speed (inter-token latency) is a <strong>proxy</strong> for confidence, not a direct measure</li><li>The model generates &quot;obvious&quot; continuations faster than surprising ones</li><li>This mirrors how the softmax probability distribution works: when one token has much higher probability than the alternatives, the computation resolves faster</li><li>For <strong>precise</strong> confidence measurement, you need actual logprobs — which LLMxRay provides through the Benchmark feature (Module 3)</li></ul><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Tokens are the atomic unit</strong> of LLM computation — not words, not characters</li><li><strong>BPE tokenization</strong> creates a vocabulary from statistical patterns, not linguistic rules</li><li><strong>Token boundaries</strong> determine what the model can and cannot reason about (letter counting, character manipulation)</li><li><strong>Language bias</strong> in tokenizers creates measurable unfairness in cost, speed, and quality across languages</li><li><strong>Speed correlates with confidence</strong> but is not identical — it&#39;s a useful approximation</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><p>For classroom or seminar discussion:</p><ol><li>If tokenizers are trained on English-dominated corpora, what would a &quot;fair&quot; multilingual tokenizer look like? Is it even possible with a fixed vocabulary size?</li><li>The &quot;strawberry&quot; problem shows that models can&#39;t reason about characters within tokens. What other seemingly simple tasks might be affected by token boundaries?</li><li>Should AI companies disclose their tokenizer&#39;s language bias? How would this change how non-English-speaking users interact with AI?</li><li>If you were designing a tokenizer for a specific domain (medical, legal, code), how would you modify the training process?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>Neural Machine Translation of Rare Words with Subword Units</td><td>Sennrich, Haddow, Birch</td><td>2016</td><td><a href="https://arxiv.org/abs/1508.07909" target="_blank" rel="noreferrer">arXiv:1508.07909</a></td></tr><tr><td>SentencePiece: A simple and language independent subword tokenizer</td><td>Kudo, Richardson</td><td>2018</td><td><a href="https://arxiv.org/abs/1808.06226" target="_blank" rel="noreferrer">arXiv:1808.06226</a></td></tr><tr><td>Language Model Tokenizers Introduce Unfairness Between Languages</td><td>Petrov, La Malfa, Torr, Bibi</td><td>2023</td><td><a href="https://arxiv.org/abs/2305.15425" target="_blank" rel="noreferrer">arXiv:2305.15425</a></td></tr><tr><td>Why Do Large Language Models Struggle to Count Letters?</td><td>Fu, Ferrando, Conde, Arriaga, Reviriego</td><td>2024</td><td><a href="https://arxiv.org/abs/2412.18626" target="_blank" rel="noreferrer">arXiv:2412.18626</a></td></tr><tr><td>Attention Is All You Need</td><td>Vaswani et al.</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr><tr><td>The Llama 3 Herd of Models</td><td>Grattafiori et al. (Meta AI)</td><td>2024</td><td><a href="https://arxiv.org/abs/2407.21783" target="_blank" rel="noreferrer">arXiv:2407.21783</a></td></tr></tbody></table><h3 id="tutorials-and-visual-explanations" tabindex="-1">Tutorials and Visual Explanations <a class="header-anchor" href="#tutorials-and-visual-explanations" aria-label="Permalink to &quot;Tutorials and Visual Explanations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Author</th><th>Link</th></tr></thead><tbody><tr><td>Let&#39;s build the GPT Tokenizer (video, 2h13m)</td><td>Andrej Karpathy</td><td><a href="https://www.youtube.com/watch?v=zduSFxRajkE" target="_blank" rel="noreferrer">YouTube</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr><tr><td>HuggingFace NLP Course, Chapter 6: Tokenizers</td><td>Hugging Face</td><td><a href="https://huggingface.co/learn/llm-course/en/chapter6/5" target="_blank" rel="noreferrer">huggingface.co/learn</a></td></tr><tr><td>LLM Sampling Parameters Explained</td><td>Let&#39;s Data Science</td><td><a href="https://letsdatascience.com/blog/llm-sampling-temperature-top-k-top-p-and-min-p-explained" target="_blank" rel="noreferrer">letsdatascience.com</a></td></tr></tbody></table><h3 id="interactive-tools" tabindex="-1">Interactive Tools <a class="header-anchor" href="#interactive-tools" aria-label="Permalink to &quot;Interactive Tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Link</th><th>What it does</th></tr></thead><tbody><tr><td>Tiktokenizer</td><td><a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">tiktokenizer.vercel.app</a></td><td>Visualize GPT tokenization with color coding</td></tr><tr><td>HuggingFace Tokenizer Playground</td><td><a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">huggingface.co/spaces/Xenova</a></td><td>Compare tokenization across open models (LLaMA, Mistral, etc.)</td></tr><tr><td>OpenAI Tokenizer</td><td><a href="https://platform.openai.com/tokenizer" target="_blank" rel="noreferrer">platform.openai.com/tokenizer</a></td><td>Official OpenAI token visualizer</td></tr></tbody></table><h3 id="related-university-courses" tabindex="-1">Related University Courses <a class="header-anchor" href="#related-university-courses" aria-label="Permalink to &quot;Related University Courses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Institution</th><th>Link</th></tr></thead><tbody><tr><td>CS224N: NLP with Deep Learning</td><td>Stanford</td><td><a href="https://web.stanford.edu/class/cs224n/" target="_blank" rel="noreferrer">web.stanford.edu/class/cs224n</a></td></tr><tr><td>11-711: Advanced NLP</td><td>CMU</td><td><a href="https://www.phontron.com/class/anlp2024/" target="_blank" rel="noreferrer">phontron.com/class/anlp2024</a></td></tr></tbody></table><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Written reflection (individual, 300 words):</strong> Describe one thing about tokenization that surprised you, with evidence from your LLMxRay experiments (include screenshots).</p><p><strong>Option B — Data analysis (individual or pairs, 1 page):</strong> Tokenize the same paragraph in 4+ languages using the HuggingFace Tokenizer Playground. Present a table of token counts, calculate the ratios vs English, and discuss the fairness implications.</p><p><strong>Option C — Presentation (groups of 2-3, 5 minutes):</strong> Design and present a &quot;tokenization challenge&quot; — a task that LLMs should be able to do but can&#39;t because of token boundaries. Demonstrate it live in LLMxRay and explain why the tokenizer is the bottleneck.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>In <strong><a href="./module-2.html">Module 2: How Does Temperature Work?</a></strong>, you&#39;ll use what you learned about tokens to understand how the model <em>chooses</em> between them. Temperature controls the probability distribution over the vocabulary — and you&#39;ll discover that it&#39;s not a linear dial but a phase transition.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 1 of 8</strong> in the LLMxRay Educators Kit <a href="./index.html">Back to Curriculum Overview</a> | <a href="./module-2.html">Next: Module 2 — How Does Temperature Work? →</a></p></div>',86)])])}const f=t(d,[["render",h]]);export{b as __pageData,f as default};
